    32: {"id": 32,"typeId": 2,"letterId": 12,"symbol": "[dʒ]","mouth": ["舌尖后端抬到上齿龈的后面，使舌中紧贴硬颚。","双唇向外撅起，做小孩子生气的样子。","气流由舌端与上齿龈之间流出，舌尖舌端接触上齿龈后立即离开，振动声带，发出[dʒ] 音。"],"words": [{"id": 192,"text": "job   [dʒɒb]   n.工作；职业；职位","word": "job","ipa": "[dʒɒb]","translation": "n.工作；职业；职位","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 193,"text": "jump   [dʒʌmp]   n.跳跃；跳动；v.跳越","word": "jump","ipa": "[dʒʌmp]","translation": "n.跳跃；跳动；v.跳越","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 194,"text": "joke   [dʒəʊk]   n.笑话；玩笑；v.说笑话","word": "joke","ipa": "[dʒəʊk]","translation": "n.笑话；玩笑；v.说笑话","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 195,"text": "jealous   ['dʒeləs]   adj.妒忌的；羡慕的；嫉妒的","word": "jealous","ipa": "['dʒeləs]","translation": "adj.妒忌的；羡慕的；嫉妒的","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10770,"text": "How is your new job?","translation": "你的新工作怎么样？","startIndex": 16,"endIndex": 18,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10771,"text": "He can jump two meters high.","translation": "他能跳两米高。","startIndex": 7,"endIndex": 10,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10772,"text": "Are you joking me?","translation": "你在逗我？","startIndex": 8,"endIndex": 13,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10773,"text": "Don't be jealous of others easily.","translation": "不要轻易地嫉妒别人。","startIndex": 9,"endIndex": 15,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
