    34: {"id": 34,"typeId": 2,"letterId": 14,"symbol": "[l]","mouth": ["舌尖轻抵上齿龈，嘴微张。","舌前部向硬颚抬起来。","口腔内冲出一股气流，使之从舌侧流出，振动声带，发出[l]音。"],"words": [{"id": 201,"text": "love   [lʌv]   v.爱；热爱；喜欢；n.爱","word": "love","ipa": "[lʌv]","translation": "v.爱；热爱；喜欢；n.爱","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 202,"text": "land   [lænd]   n.陆地；国土；土地","word": "land","ipa": "[lænd]","translation": "n.陆地；国土；土地","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 203,"text": "lazy   ['leɪzɪ]   adj.懒惰的；懒散的","word": "lazy","ipa": "['leɪzɪ]","translation": "adj.懒惰的；懒散的","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 204,"text": "little   ['lɪtl]   adj.小的；幼小的；短的","word": "little","ipa": "['lɪtl]","translation": "adj.小的；幼小的；短的","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10779,"text": "I love my dad.","translation": "我爱我的爸爸。","startIndex": 2,"endIndex": 5,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10780,"text": "The sailors couldn't see land for many days.","translation": "水手们好几天看不到陆地。","startIndex": 25,"endIndex": 28,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10781,"text": "How can you be so lazy?","translation": "你怎么能这么懒？","startIndex": 18,"endIndex": 21,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10782,"text": "Can I have a little more water?","translation": "我能再要点水吗？","startIndex": 13,"endIndex": 18,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
    35: {"id": 35,"typeId": 2,"letterId": 15,"symbol": "[m]","mouth": ["软颚下垂，双唇闭拢，舌部放平。","口形保持自然不说话状态。","气流由鼻腔流出，气振声带，发出[m]音。"],"words": [{"id": 205,"text": "me   [mi:]   pron.我(宾格)","word": "me","ipa": "[mi:]","translation": "pron.我(宾格)","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 206,"text": "him   [hɪm]   pron.他(he的宾格)","word": "him","ipa": "[hɪm]","translation": "pron.他(he的宾格)","startIndex": 2,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 207,"text": "meat   [mi:t]   n.肉","word": "meat","ipa": "[mi:t]","translation": "n.肉","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 208,"text": "swim   [swɪm]   v.游泳；n.游泳","word": "swim","ipa": "[swɪm]","translation": "v.游泳；n.游泳","startIndex": 3,"endIndex": 3,"hasAudio": true,"hasImage": true},{"id": 209,"text": "woman   ['wʊmən]   n.妇女；女人","word": "woman","ipa": "['wʊmən]","translation": "n.妇女；女人","startIndex": 2,"endIndex": 2,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10783,"text": "Can you help me?","translation": "你能帮我吗？","startIndex": 13,"endIndex": 14,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10784,"text": "I want to help him.","translation": "我想帮他。","startIndex": 15,"endIndex": 17,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10785,"text": "He loves eating meat.","translation": "他爱吃肉。","startIndex": 16,"endIndex": 19,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10786,"text": "He likes swimming.","translation": "他喜欢游泳。","startIndex": 9,"endIndex": 16,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10787,"text": "Who is that woman?","translation": "那个女人是谁？","startIndex": 12,"endIndex": 16,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
    36: {"id": 36,"typeId": 2,"letterId": 16,"symbol": "[n]","mouth": ["舌尖轻触上齿龈。","舌叶轻碰硬颚。","气流由鼻腔流出，气振声带，发出[n]音。"],"words": [{"id": 210,"text": "no   [nəʊ]   adv.不","word": "no","ipa": "[nəʊ]","translation": "adv.不","startIndex": 0,"endIndex": 0,"hasAudio": true,"hasImage": true},{"id": 211,"text": "rain   [reɪn]   n.雨；雨水；v.下雨","word": "rain","ipa": "[reɪn]","translation": "n.雨；雨水；v.下雨","startIndex": 3,"endIndex": 3,"hasAudio": true,"hasImage": true},{"id": 212,"text": "town   [taʊn]   n.城市；城镇","word": "town","ipa": "[taʊn]","translation": "n.城市；城镇","startIndex": 3,"endIndex": 3,"hasAudio": true,"hasImage": true},{"id": 213,"text": "winter   ['wɪntə(r)]   n.冬季；冬天；adj.冬天的","word": "winter","ipa": "['wɪntə(r)]","translation": "n.冬季；冬天；adj.冬天的","startIndex": 2,"endIndex": 2,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10788,"text": "No, I don't like it at all.","translation": "不，我一点都不喜欢它。","startIndex": 0,"endIndex": 1,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10789,"text": "It rained heavily last night.","translation": "昨天晚上雨下得很大。","startIndex": 3,"endIndex": 8,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10790,"text": "My uncle lives in a small town now.","translation": "我叔叔现在住在一个小镇里。","startIndex": 26,"endIndex": 29,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10791,"text": "We can make snowman in winter.","translation": "冬天我们可以堆雪人。","startIndex": 23,"endIndex": 28,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
