    56: {"id": 56,"typeId": 3,"letterId": 27,"symbol": "[ɔː]","mouth": ["从汉语拼音的“凹”出发，以获得正确的舌高、舌位。","将上下唇略为张大，舌前部压低，舌身尽量往后缩，保持这一口型不变。","气流从口腔中流出，振动声带，发出[ɔ:]音。"],"words": [{"id": 263,"text": "saw   [sɔː]   动词see的过去式","word": "saw","ipa": "[sɔː]","translation": "动词see的过去式","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 264,"text": "draw   [drɔː]   v.拖；接近；画","word": "draw","ipa": "[drɔː]","translation": "v.拖；接近；画","startIndex": 2,"endIndex": 3,"hasAudio": true,"hasImage": true},{"id": 265,"text": "raw   [rɔː]   adj.未加工的；生的","word": "raw","ipa": "[rɔː]","translation": "adj.未加工的；生的","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 266,"text": "awful   ['ɔːfl]   adj.糟糕的；可怕的；充满敬畏的","word": "awful","ipa": "['ɔːfl]","translation": "adj.糟糕的；可怕的；充满敬畏的","startIndex": 0,"endIndex": 1,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10841,"text": "I saw our English teacher just now.","translation": "我刚才看到我们的英语老师了。","startIndex": 2,"endIndex": 4,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10842,"text": "He drew a picture for his mother.","translation": "他给她的妈妈画了一幅画。","startIndex": 3,"endIndex": 6,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10843,"text": "I do not like raw onions.","translation": "我不喜欢生洋葱。","startIndex": 14,"endIndex": 16,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10844,"text": "The weather is awful.","translation": "天气太糟了。","startIndex": 15,"endIndex": 19,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
