    63: {"id": 63,"typeId": 3,"letterId": 34,"symbol": "[i:]","mouth": ["保持唇形扁平，上下齿几乎全合，口腔肌肉松弛，像是在微笑。","使舌尖轻抵下齿，舌前部尽量向硬颚抬起，但不要贴紧硬颚。","想象汉语中的“衣”，使气流从口腔冲出，振动声带发音。"],"words": [{"id": 280,"text": "tea   [ti:]   n.茶；茶叶","word": "tea","ipa": "[ti:]","translation": "n.茶；茶叶","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 281,"text": "read   [ri:d]   v.识字；阅读；朗读；理解；读到","word": "read","ipa": "[ri:d]","translation": "v.识字；阅读；朗读；理解；读到","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 282,"text": "meat   [mi:t]   n.肉","word": "meat","ipa": "[mi:t]","translation": "n.肉","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 283,"text": "teach   [ti:tʃ]   vt.教；教导；教授","word": "teach","ipa": "[ti:tʃ]","translation": "vt.教；教导；教授","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10858,"text": "I would like a cup of tea.","translation": "我想要一杯茶。","startIndex": 22,"endIndex": 24,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10859,"text": "I like reading.","translation": "我喜欢读书。","startIndex": 7,"endIndex": 13,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10860,"text": "Don't eat so much meat.","translation": "不要吃那么多肉。","startIndex": 18,"endIndex": 21,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10861,"text": "He teaches history in a school.","translation": "他在一所学校里教历史。","startIndex": 3,"endIndex": 9,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
    64: {"id": 64,"typeId": 3,"letterId": 34,"symbol": "[e]","mouth": ["保持唇形扁平，开口稍大于[I]，上下齿间可容纳一个食指，口腔肌肉松弛。","舌尖轻抵下齿，舌前部稍抬起，比发[I]时略低，射中的两侧碰到后面的大牙。","从汉语的“挨”出发，做出发“挨”音的趋势，但不出声。最后让一股极为短促的气流从口腔中冲出，振动声带，发出[e]音。"],"words": [{"id": 284,"text": "heavy   ['hevɪ]   adj.大(量)的；重的；沉重的；猛烈的","word": "heavy","ipa": "['hevɪ]","translation": "adj.大(量)的；重的；沉重的；猛烈的","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 285,"text": "weather   ['weðə(r)]   n.天气；气象","word": "weather","ipa": "['weðə(r)]","translation": "n.天气；气象","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 286,"text": "peasant   ['peznt]   n.农民","word": "peasant","ipa": "['peznt]","translation": "n.农民","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 287,"text": "pleasure   ['pleʒə(r)]   n.愉快；高兴","word": "pleasure","ipa": "['pleʒə(r)]","translation": "n.愉快；高兴","startIndex": 2,"endIndex": 3,"hasAudio": true,"hasImage": true},{"id": 288,"text": "treasure   ['treʒə(r)]   n.财富；宝物;vt.珍藏；珍视","word": "treasure","ipa": "['treʒə(r)]","translation": "n.财富；宝物;vt.珍藏；珍视","startIndex": 2,"endIndex": 3,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10862,"text": "The box is too heavy.","translation": "这个箱子太沉了。","startIndex": 15,"endIndex": 19,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10863,"text": "What's the weather outside?","translation": "外面的天气怎么样？","startIndex": 11,"endIndex": 17,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10864,"text": "Her grandfather is a peasant.","translation": "她的祖父是个农民。","startIndex": 21,"endIndex": 27,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10865,"text": "He brought a lot of pleasure to us.","translation": "他给我们带来了很多欢乐。","startIndex": 20,"endIndex": 27,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10866,"text": "The old man left a lot of treasure after he died.","translation": "老人死后留下来很多财富。","startIndex": 26,"endIndex": 33,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
