    67: {"id": 67,"typeId": 3,"letterId": 35,"symbol": "[ei]","mouth": ["从汉语中的“黑”的韵母“ei”出发，以获得正确的舌高、舌位。","将双唇稍微长大，成微笑趋势。","从口腔中冲出一股气流，振动声带，发出[ei]音。"],"words": [{"id": 296,"text": "eight   [eɪt]   num.八","word": "eight","ipa": "[eɪt]","translation": "num.八","startIndex": 0,"endIndex": 1,"hasAudio": true,"hasImage": true},{"id": 297,"text": "neighbor   ['neɪbə]   n.邻居；邻国","word": "neighbor","ipa": "['neɪbə]","translation": "n.邻居；邻国","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 298,"text": "reign   [reɪn]   n.君主统治；在位期;v.统治；支配","word": "reign","ipa": "[reɪn]","translation": "n.君主统治；在位期;v.统治；支配","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10874,"text": "There are eight students in the classroom now.","translation": "教室里现在有八名学生。","startIndex": 10,"endIndex": 14,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10875,"text": "Our neighbor planted an apple tree in their yard.","translation": "我们的邻居在他们的院子里种了一棵苹果树。","startIndex": 4,"endIndex": 11,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10876,"text": "The king reigned the land.","translation": "国王统治着这片土地。","startIndex": 9,"endIndex": 15,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
