    82: {"id": 82,"typeId": 3,"letterId": 44,"symbol": "[ʊ]","mouth": ["从汉语拼音\"u\"出发，保持正确的舌高、舌位。","使双唇趋于原形，并向后略缩。","极为短促的气流从口腔冲出，微振声带，发出[u]音。"],"words": [{"id": 303,"text": "book   [bʊk]   n.书；本子；v.预订","word": "book","ipa": "[bʊk]","translation": "n.书；本子；v.预订","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 304,"text": "look   [lʊk]   v.看；寻找","word": "look","ipa": "[lʊk]","translation": "v.看；寻找","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 305,"text": "cook   [kʊk]   n.厨师；v.烹调；烧煮","word": "cook","ipa": "[kʊk]","translation": "n.厨师；v.烹调；烧煮","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 306,"text": "football   ['fʊtbɔːl]   n.足球；橄榄球","word": "football","ipa": "['fʊtbɔːl]","translation": "n.足球；橄榄球","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10881,"text": "This book is very interesting.","translation": "这本书非常有趣。","startIndex": 5,"endIndex": 8,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10882,"text": "May I have a look?","translation": "我能看一下吗？","startIndex": 13,"endIndex": 16,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10883,"text": "Who cooked the dinner?","translation": "谁做的晚餐啊？","startIndex": 4,"endIndex": 9,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10884,"text": "He likes playing football.","translation": "他喜欢踢足球。","startIndex": 17,"endIndex": 24,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
    83: {"id": 83,"typeId": 3,"letterId": 44,"symbol": "[uː]","mouth": ["从汉语拼音“u”出发，保持正确的舌高、舌位。","使双唇趋于圆形，并向后略缩（与汉语拼音的“u”音相比较而言）。","气流从口腔冲出，振动声带，发出[u:]音。"],"words": [{"id": 307,"text": "cool   [kuːl]   adj.凉爽的；凉的","word": "cool","ipa": "[kuːl]","translation": "adj.凉爽的；凉的","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 308,"text": "room   [ruːm]   n.房间；空间","word": "room","ipa": "[ruːm]","translation": "n.房间；空间","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 309,"text": "moon   [muːn]   n.月亮；月球","word": "moon","ipa": "[muːn]","translation": "n.月亮；月球","startIndex": 1,"endIndex": 2,"hasAudio": true,"hasImage": true},{"id": 310,"text": "school   [skuːl]   n.学校；学派","word": "school","ipa": "[skuːl]","translation": "n.学校；学派","startIndex": 3,"endIndex": 4,"hasAudio": true,"hasImage": true}],"sentences": [{"id": 10885,"text": "The weather is very cool.","translation": "天气很凉爽。","startIndex": 20,"endIndex": 23,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10886,"text": "Who is in the room now?","translation": "现在谁在屋里呢？","startIndex": 14,"endIndex": 17,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10887,"text": "There is a full moon in the sky.","translation": "天上有一轮满月。","startIndex": 16,"endIndex": 19,"hasMaleAudio": true,"hasFemaleAudio": true},{"id": 10888,"text": "I go to school by bus.","translation": "我乘公交去学校。","startIndex": 8,"endIndex": 13,"hasMaleAudio": true,"hasFemaleAudio": true}],"hasImage": true,"hasAudio": true},
